def is_possible_to_split(nums):
    # Dictionary to count frequency of each number
    freq = {}
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # If any number occurs more than twice, impossible to split
    for count in freq.values():
        if count > 2:
            return False
    return True
